trigger OpportunityTrigger on Opportunity (after insert, after update) {

    Set<Id> accountIds = new Set<Id>();

    if (Trigger.isInsert) {
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    }

    if (Trigger.isUpdate) {
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId != null) {
                Opportunity old = Trigger.oldMap.get(opp.Id);
                if (old.StageName != opp.StageName || old.Amount != opp.Amount) {
                    accountIds.add(opp.AccountId);
                }
            }
        }
    }

    if (!accountIds.isEmpty()) {
        // Single @future call per transaction rather than per-record,
        // to stay within the 50-future-per-transaction governor limit
        // when CPQ sends batches of 200.
        AccountRatingService.recalculate(new List<Id>(accountIds));
    }
}
