public with sharing class AccountRatingService {

    /**
     * Recalculates the Rating field for the given accounts based on their
     * open (non-Closed-Won, non-Closed-Lost) opportunity pipeline.
     *
     * Hot  – at least one open Opportunity with Amount >= 100 000
     * Warm – has open Opportunities, but none >= 100 000
     * Cold – no open Opportunities
     *
     * Runs asynchronously (separate transaction) so that the calling
     * Opportunity save stays fast.
     */
    @future
    public static void recalculate(List<Id> accountIds) {

        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // One SOQL to gather every open Opportunity for the affected accounts.
        // We check Amount in memory to avoid a second query.
        Set<Id> hotAccountIds   = new Set<Id>();
        Set<Id> warmAccountIds  = new Set<Id>();

        for (Opportunity opp : [
            SELECT AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND StageName NOT IN ('Closed Won', 'Closed Lost')
        ]) {
            warmAccountIds.add(opp.AccountId);
            if (opp.Amount != null && opp.Amount >= 100000) {
                hotAccountIds.add(opp.AccountId);
            }
        }

        // Determine new rating; only write when it actually changed.
        List<Account> toUpdate = new List<Account>();

        for (Account acc : [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            String newRating;
            if (hotAccountIds.contains(acc.Id)) {
                newRating = 'Hot';
            } else if (warmAccountIds.contains(acc.Id)) {
                newRating = 'Warm';
            } else {
                newRating = 'Cold';
            }

            if (acc.Rating != newRating) {
                toUpdate.add(new Account(Id = acc.Id, Rating = newRating));
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
