public with sharing class LineItemDiscountHandler {

    public static void onBeforeInsert(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        // 1. Gather the distinct Product2 Ids we need to look up.
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }
        if (productIds.isEmpty()) {
            return;
        }

        // 2. ONE bulk SOQL query – regardless of record count.
        Map<Id, Product2> productMap = new Map<Id, Product2>(
            [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]
        );

        // 3. Resolve the standard discount per product.
        //    We call PricingRules.standardDiscountForFamily, which contains the
        //    same rules as standardDiscountFor but does NOT execute SOQL,
        //    so we stay well inside the 100-query governor limit even for
        //    200-line (or larger) CPQ quotes.
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                Product2 prod = productMap.get(line.Product2Id);
                if (prod != null) {
                    line.Discount = PricingRules.standardDiscountForFamily(prod.Family);
                }
            }
        }
    }
}
