```apex
trigger CaseTrigger on Case (after update) {

    if (Trigger.isAfter && Trigger.isUpdate) {

        // Collect case Ids that transitioned to closed AND have a contact.
        List<Id> qualifyingIds = new List<Id>();

        for (Case c : Trigger.new) {
            Case before = Trigger.oldMap.get(c.Id);

            // Only act on the transition: not-closed → closed.
            if (c.IsClosed && !before.IsClosed && c.ContactId != null) {
                qualifyingIds.add(c.Id);
            }
        }

        if (qualifyingIds.isEmpty()) {
            return;
        }

        // Salesforce allows at most 50 concurrent Queueable jobs in the
        // Flex Queue.  A nightly API cleanup can close 200 cases in one
        // transaction, so we chunk into groups of 50 to stay under the cap.
        // Each Queueable still processes its cases independently (per-case
        // try/catch + allOrNone=false), giving failure isolation.
        final Integer BATCH_SIZE = 50;

        Integer idx = 0;
        while (idx < qualifyingIds.size()) {
            List<Id> chunk = new List<Id>();
            Integer end = Math.min(idx + BATCH_SIZE, qualifyingIds.size());

            for (Integer i = idx; i < end; i++) {
                chunk.add(qualifyingIds[i]);
            }

            System.enqueueJob(new CaseSurveyJob(chunk));
            idx = end;
        }
    }
}
